# Sign-up and login done right: a unique salt and a slow hash per user.
import hashlib
import hmac

users = {}

def hash_password(password, salt):
    return hashlib.pbkdf2_hmac("sha256", password.encode(), salt, 100_000).hex()

def register(name, password, salt):
    users[name] = {"salt": salt, "hash": hash_password(password, salt)}

def login(name, password):
    user = users.get(name)
    if not user:
        return False
    attempt = hash_password(password, user["salt"])
    return hmac.compare_digest(attempt, user["hash"])   # constant-time comparison

# In a real app each salt comes from os.urandom(16); fixed here so the output is repeatable.
register("ana", "correct horse battery staple", bytes.fromhex("8f1a2b3c4d5e6f708192a3b4c5d6e7f8"))
